 "dule":{"name": "独乐寺观音阁", "items": [{"id": "dule-front-2020", "title": "两重檐之间藏着暗层", "tag": "正面 · 2020现状", "chapter": 0, "angle": "front", "modelLabel": "回到观音阁全貌", "look": "比较上下檐口、暗层与上层栏杆。现状可见的细擎檐柱、红围护和匾额尚未完整进入辽构骨架模型。", "limit": "2020-05-04；有树木、香炉遮挡。不能直接用照片测柱网或把后加支柱当辽构原柱。"}, {"id": "dule-front-2013", "title": "另一年光照下的正面", "tag": "正面 · 2013现状", "chapter": 0, "angle": "front", "modelLabel": "回到观音阁全貌", "look": "对读两张正面，辨认灰瓦、栏杆与檐下木构，保留拍摄时的遮挡和色调。", "limit": "2013-10-04；拍摄与修缮分期不能等同。未用跨年色差推断历史原色。"}, {"id": "dule-oblique-2014", "title": "从斜侧追踪山面与檐角", "tag": "斜侧 · 两檐与山面", "chapter": 4, "angle": "oblique", "modelLabel": "观察本阁歇山屋架", "look": "把长坡、山坡与两层檐角联系起来。转到模型山面并打开瓦面层，比较实际屋角与仍属推定的模型轮廓。", "limit": "2014-07-16；斜侧照片而非纯侧立面，罗盘方位未核。左上角邻近建筑仅作现场语境，不作为观音阁构件依据。"}, {"id": "dule-plaque-2024", "title": "匾额两侧，分辨上檐铺作", "tag": "细部 · 上檐匾额与铺作", "chapter": 2, "angle": "detail", "modelLabel": "进入上檐两下昂局部", "look": "放大辨认“观音之阁”匾、梁面色彩、瓦口与两侧铺作。回看模型进入上檐两下昂方向诊断，区别下檐叉柱节点。", "limit": "2024-01-08；1702×1276为原片像素上限。模型未复原昂嘴、真实斜率、卯口或匾额书法；整阁上檐逐攒仍简化。", "node": "upper"}, {"id": "dule-interior-2023", "title": "从入口看贯通空间与维修现场", "tag": "现状内景 · 2023", "chapter": 3, "angle": "interior", "modelLabel": "进入空井剖面", "look": "保留门框、造像、周边柱架与维修脚手架的完整上下文。沿观音像向上追踪楼层，和模型中央贯通空间对照。", "limit": "EditQ，2023-03-19，4000×3000。脚手架与造像遮挡空井；不是无遮挡井口测绘，不把维修杆架误读成原构。"}, {"id": "dule-west-1932", "title": "西面各层斗栱的原刊旧影", "tag": "历史西面 · 图31、32", "chapter": 4, "angle": "side", "modelLabel": "观察歇山与层间木构", "look": "原刊PDF第79页。下图图注明确“观音阁西面各层斗栱”，两檐、暗层和平坐在同一侧向画面中可对读。整页和原图注保留。", "limit": "1932年刊载，拍摄日未载；历史侧向局部，并非当前完整侧立面。原扫描1474×2348，不放大冒充新拍高清；精确卯口仍有遮挡。"}, {"id": "dule-inner-1932", "title": "中层内槽，追踪铺作后尾", "tag": "历史内槽 · 图39、40", "chapter": 3, "angle": "interior", "modelLabel": "进入层间空井剖面", "look": "原刊PDF第87页，图39、40对照中层内槽当心间、次间的补间铺作后尾，观察水平木件与上部柱架的位置。", "limit": "1932年刊载。保留整页两图；这是内槽与后尾证据，不能将其中每处连接标成模型下檐叉柱槽口，也不据暗部量取接头深度。"}, {"id": "dule-stair-1932", "title": "从梯口向上层外檐看", "tag": "历史梯口 · 图41、42", "chapter": 3, "angle": "interior", "modelLabel": "进入空井与楼梯剖面", "look": "原刊PDF第90页，上图为中层内槽转角补间，下图图注明确上层外檐柱头与补间；保留梯口、栏杆和层间木作的空间上下文。", "limit": "1932年刊载，扫描灰阶与网纹保留。梯口图不证明当前楼梯步数与起止标高；模型楼梯仍为关系示意。"}, {"id": "dule-upper-corner-1932", "title": "上层转角，和内部承托对读", "tag": "历史节点 · 图43、44", "chapter": 4, "angle": "detail", "modelLabel": "回到整阁定位上层檐角", "look": "原刊PDF第93页，两张原图分别记录上层外檐转角和上层内檐铺作相关部位，能看到多向构件与后尾。", "limit": "1932年刊载。正式卷尚无准确转角局部，回看整阁保留檐角语境；不跳到正身节点冒充转角，真实互锁与逐攒差异仍待核。"}, {"id": "dule-shaft-1932", "title": "从空井仰看上层内部", "tag": "历史空井 · 图46、47", "chapter": 5, "angle": "interior", "modelLabel": "定位空井上方构造", "look": "原刊PDF第96页，图46为上层内部梁架，图47保留造像头部与周边内檐铺作的空间关系。把局部构件放回贯通空间理解。", "limit": "1932年刊载，旧扫描1500×2441。造像与阴影仍遮挡部分井口；不把照片里的内部梁架直接当作模型八边藻井占位已核定。"}], "relatedSources": [{"title": "2026年新华社：观音阁内部榫卯与造像实拍", "url": "https://english.news.cn/20260729/554a0060928e44e2bc56acda4e9756d8/c.html", "note": "2026-07-22拍摄，2026-07-29刊载，摄影Sun Fanyue / Li Ran。图2由来源明确标为观音阁内部榫卯；进入原站看图。尚未取得再分发许可，不复制到本地图录或R2。"}, {"title": "北面航拍线索：原作者组图", "url": "https://www.sina.cn/news/detail/5301373466055191.html", "note": "多肉闹海，2026-05-22发布；作者列“图十 观音阁北面”，多次拍摄。当前页面抓取只返回前9图，北面单图尚未核验；保留可追踪原作入口，不计作已取得的背面照片。"}], "intro": "5张现状照片与5页1932年历史摄影图版。历史图版保留整页与图注，点击查看原扫描；各图年代和可见范围分别注明。"},
